'use client';

import { useState, useEffect, useRef } from 'react';
import LoadingOverlay from '@/components/LoadingOverlay';
import { useAdminAuth } from '@/hooks/useAdminAuth';
import { usePolling } from '@/hooks/usePolling';

export default function CourseMapping() {
  const [courses, setCourses] = useState([]);
  const [faculties, setFaculties] = useState([]);
  const [mappings, setMappings] = useState({}); // { course_id: { faculty_ids: [...], co_coordinator_id: null } }
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [toast, setToast] = useState(null);
  const isDirtyRef = useRef(false);

  const showToast = (type, msg) => {
    setToast({ type, msg });
    setTimeout(() => setToast(null), 3000);
  };

  const { token: authToken, isReady } = useAdminAuth();

  useEffect(() => {
    if (isReady) fetchData(true);
  }, [isReady]);

  const fetchData = async (isInitial = false) => {
    if (isInitial) setLoading(true);
    try {
      const token = authToken;
      const headers = { 'Authorization': `Bearer ${token}` };

      // Fetch courses, faculties, and current mappings in parallel
      const [cRes, fRes, mRes] = await Promise.all([
        fetch('/api/courses', { headers }),
        fetch('/api/users?role=faculty&status=active', { headers }),
        fetch('/api/mapping', { headers })
      ]);

      if (cRes.ok) setCourses(await cRes.json());
      if (fRes.ok) setFaculties(await fRes.json());
      if (mRes.ok) {
        const mappingData = await mRes.json();
        const initialMap = {};
        for (const [cid, facs] of Object.entries(mappingData)) {
          const co = facs.find(f => f.is_co_coordinator);
          initialMap[cid] = {
            faculty_ids: facs.map(f => f.id),
            co_coordinator_id: co ? co.id : (facs[0]?.id || null)
          };
        }
        if (!isDirtyRef.current) {
          setMappings(initialMap);
        }
      }
    } catch (e) {
      console.error(e);
      if (isInitial) showToast('error', 'Error loading data');
    } finally {
      if (isInitial) setLoading(false);
    }
  };

  // Auto-refresh courses and mappings silently every 30s (skips when user has pending unsaved edits)
  usePolling(() => { if (!processing && !isDirtyRef.current) fetchData(false); }, 30_000, isReady);

  const handleSelectFaculty = (courseId, facultyId) => {
    if (!facultyId) return; // Empty selection
    isDirtyRef.current = true;
    
    setMappings(prev => {
      const current = prev[courseId] || { faculty_ids: [], co_coordinator_id: null };
      // If already added, don't add again
      if (current.faculty_ids.includes(facultyId)) return prev;
      
      // Limit to 4
      if (current.faculty_ids.length >= 4) {
        showToast('error', 'You can assign a maximum of 4 faculties per course.');
        return prev;
      }
      
      const newFids = [...current.faculty_ids, facultyId];
      return { 
        ...prev, 
        [courseId]: {
          faculty_ids: newFids,
          co_coordinator_id: current.co_coordinator_id || facultyId
        }
      };
    });
  };

  const handleRemoveFaculty = (courseId, facultyId) => {
    isDirtyRef.current = true;
    setMappings(prev => {
      const current = prev[courseId] || { faculty_ids: [], co_coordinator_id: null };
      const newFids = current.faculty_ids.filter(id => id !== facultyId);
      let newCo = current.co_coordinator_id;
      if (newCo === facultyId) {
        newCo = newFids[0] || null;
      }
      return { 
        ...prev, 
        [courseId]: {
          faculty_ids: newFids,
          co_coordinator_id: newCo
        }
      };
    });
  };

  const handleSetCoCoordinator = (courseId, facultyId) => {
    isDirtyRef.current = true;
    setMappings(prev => {
      const current = prev[courseId] || { faculty_ids: [], co_coordinator_id: null };
      return {
        ...prev,
        [courseId]: {
          ...current,
          co_coordinator_id: facultyId
        }
      };
    });
  };

  const handleSaveMapping = async (courseId) => {
    setProcessing(true);
    try {
      const token = authToken;
      const current = mappings[courseId] || { faculty_ids: [], co_coordinator_id: null };
      const payload = {
        course_id: courseId,
        faculty_ids: current.faculty_ids,
        co_coordinator_id: current.co_coordinator_id
      };

      const res = await fetch('/api/mapping', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      if (res.ok) {
        isDirtyRef.current = false;
        showToast('success', 'Mapping and Co-coordinator saved successfully');
      } else {
        const data = await res.json();
        showToast('error', data.error || 'Failed to save mapping');
      }
    } catch (e) {
      showToast('error', 'Network error');
    } finally {
      setProcessing(false);
    }
  };

  const getFacultyName = (id) => {
    const f = faculties.find(f => f.id === id);
    return f ? f.name : 'Unknown';
  };

  return (
    <div style={{ position: 'relative' }}>
      {processing && <LoadingOverlay />}
      
      {toast && (
        <div style={{
          position: 'fixed', top: '20px', right: '20px', zIndex: 9999,
          padding: '14px 20px', borderRadius: '10px', fontWeight: 600, fontSize: '14px',
          backgroundColor: toast.type === 'success' ? '#ecfdf5' : '#fef2f2',
          color: toast.type === 'success' ? '#065f46' : '#991b1b',
          border: `1px solid ${toast.type === 'success' ? '#6ee7b7' : '#fca5a5'}`,
          boxShadow: '0 4px 20px rgba(0,0,0,0.12)'
        }}>
          {toast.msg}
        </div>
      )}

      <div className="header">
        <div>
          <h2 style={{ fontSize: '22px', fontWeight: 700 }}>Course-Faculty Mapping</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: '13px' }}>Assign up to 4 faculties per course.</p>
        </div>
        <button
          className="btn-small"
          style={{ padding: '10px 16px', borderRadius: '8px', border: '1px solid var(--border-color)', background: 'transparent', cursor: 'pointer' }}
          onClick={fetchData}
        >
          ↻ Refresh
        </button>
      </div>

      <div className="table-container">
        {loading ? <p style={{ padding: '20px', color: '#888' }}>Loading courses and faculties...</p> : (
          <table>
            <thead>
              <tr>
                <th style={{ width: '20%' }}>Course</th>
                <th style={{ width: '10%' }}>Semester</th>
                <th style={{ width: '50%' }}>Assigned Faculty (Max 4)</th>
                <th style={{ width: '20%' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {courses.map(c => {
                const current = mappings[c.id] || { faculty_ids: [], co_coordinator_id: null };
                const assigned = current.faculty_ids;
                return (
                  <tr key={c.id}>
                    <td style={{ fontWeight: 600 }}>
                      <span style={{ color: 'var(--primary)', marginRight: '8px' }}>{c.course_code}</span>
                      <br/>{c.name}
                    </td>
                    <td>{c.semester}</td>
                    <td>
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginBottom: '10px' }}>
                        {assigned.map(fid => {
                          const isCo = current.co_coordinator_id === fid;
                          return (
                            <div key={fid} style={{ 
                              display: 'flex', alignItems: 'center', gap: '8px', 
                              padding: '6px 12px', borderRadius: '6px', 
                              backgroundColor: isCo ? '#fef3c7' : '#eff6ff', 
                              border: `1px solid ${isCo ? '#fde68a' : '#bfdbfe'}`, 
                              fontSize: '13px', color: isCo ? '#92400e' : '#1e40af' 
                            }}>
                              <span style={{ fontWeight: isCo ? 'bold' : 'normal' }}>
                                {isCo ? '👑 ' : ''}{getFacultyName(fid)}
                              </span>
                              {!isCo && (
                                <button
                                  onClick={() => handleSetCoCoordinator(c.id, fid)}
                                  title="Make Co-coordinator"
                                  style={{ background: 'none', border: 'none', color: '#b45309', cursor: 'pointer', fontSize: '11px', textDecoration: 'underline', padding: 0 }}
                                >
                                  Make Co
                                </button>
                              )}
                              <button 
                                onClick={() => handleRemoveFaculty(c.id, fid)}
                                style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontWeight: 'bold', marginLeft: '4px' }}
                              >×</button>
                            </div>
                          );
                        })}
                        {assigned.length === 0 && <span style={{ color: '#94a3b8', fontSize: '13px', fontStyle: 'italic' }}>Unassigned</span>}
                      </div>
                      
                      {assigned.length < 4 && (
                        <select 
                          className="input-field" 
                          style={{ padding: '6px', fontSize: '13px' }}
                          onChange={(e) => {
                            handleSelectFaculty(c.id, parseInt(e.target.value));
                            e.target.value = "";
                          }}
                          defaultValue=""
                        >
                          <option value="" disabled>+ Add Faculty</option>
                          {faculties.filter(f => !assigned.includes(f.id)).map(f => (
                            <option key={f.id} value={f.id}>{f.name} ({f.extra_info?.department || 'N/A'})</option>
                          ))}
                        </select>
                      )}
                    </td>
                    <td>
                      <button 
                        className="btn-primary" 
                        style={{ margin: 0, padding: '8px 16px', fontSize: '13px', width: 'auto' }}
                        onClick={() => handleSaveMapping(c.id)}
                      >
                        Save Mapping
                      </button>
                    </td>
                  </tr>
                );
              })}
              {courses.length === 0 && (
                <tr><td colSpan="4" style={{ textAlign: 'center', padding: '30px', color: '#888' }}>No courses found.</td></tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import LoadingOverlay from '@/components/LoadingOverlay';
import { useAdminAuth } from '@/hooks/useAdminAuth';
import { usePolling } from '@/hooks/usePolling';

export default function AdminDashboard() {
  const router = useRouter();
  const [stats, setStats] = useState({ faculty: 0, students: 0, courses: 0 });
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);

  const { token, isReady } = useAdminAuth();

  const fetchDashboardData = useCallback(async () => {
    try {
      const [statsRes, logsRes] = await Promise.all([
        fetch('/api/stats', { headers: { 'Authorization': `Bearer ${token}` } }),
        fetch('/api/logs?limit=8', { headers: { 'Authorization': `Bearer ${token}` } })
      ]);

      if (statsRes.status === 401 || logsRes.status === 401) {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        window.location.href = '/';
        return;
      }

      if (statsRes.ok) setStats(await statsRes.json());
      if (logsRes.ok) setLogs(await logsRes.json());
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [token]);

  useEffect(() => {
    if (isReady) fetchDashboardData();
  }, [isReady, fetchDashboardData]);

  // Auto-refresh every 15 seconds
  usePolling(fetchDashboardData, 15_000, isReady);

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleString();
  };

  const downloadDocs = async () => {
    const { default: jsPDF } = await import('jspdf');
    const doc = new jsPDF();
    
    doc.setFont("helvetica", "bold");
    doc.setFontSize(22);
    doc.setTextColor(79, 70, 229);
    doc.text('CodeRank Backend Architecture Guide', 14, 22);
    
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.setTextColor(100);
    doc.text(`Generated: ${new Date().toLocaleString()} | System Documentation`, 14, 30);
    doc.line(14, 33, 196, 33);
    
    let y = 42;
    const printSectionHeader = (title) => {
      if (y > 250) { doc.addPage(); y = 20; }
      doc.setFont("helvetica", "bold");
      doc.setFontSize(14);
      doc.setTextColor(30, 41, 59);
      doc.text(title, 14, y);
      y += 8;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(71, 85, 105);
    };

    const printParagraph = (text) => {
      const lines = doc.splitTextToSize(text, 180);
      lines.forEach(line => {
        if (y > 270) { doc.addPage(); y = 20; }
        doc.text(line, 14, y);
        y += 6;
      });
      y += 4;
    };

    printSectionHeader('1. Executive Overview');
    printParagraph('CodeRank is a secure, serverless coding playground and dynamic practical management system built on Next.js 16. The backend leverages Neon Serverless Postgres for relational storage and local/remote Docker compiler containers for sandboxed standard I/O execution.');

    printSectionHeader('2. Database Schema Architecture');
    printParagraph('The relational database uses Neon Postgres and comprises key tables:\n' +
      '- users: Mapped to email, password, and roles (admin, faculty, student).\n' +
      '- courses: Tracks name, course_code, status, and semester.\n' +
      '- practicals: Stores title, description, allowed_languages, difficulty, and total_marks.\n' +
      '- practical_test_cases: Maps input, expected output, and partial marks per case.\n' +
      '- practical_submissions: Stores user code, selected language, status, and score results.\n' +
      '- practical_submission_cases: Granular evaluation report per test case.');

    printSectionHeader('3. Dynamic Execution & Sandboxing');
    printParagraph('When a student runs or submits code, the request is intercepted by language execution managers (python-run, cpp-run, java-run, c-run, javascript-run). It mounts the source code and input text inside isolated Docker containers, compiles if necessary, and executes the program safely under resource constraints (128MB memory limit, 5s timeout).');

    printSectionHeader('4. Grading and Normalization Formula');
    printParagraph('During submission, the system evaluates all test cases. The raw marks are aggregated. The overall score is then normalized to a 10-point scale using the formula:\n' +
      '   Normalized Marks = (Raw Marks / Total Marks) * 10\n' +
      'The result is rounded to 2 decimal places and stored in the database.');

    doc.save('CodeRank_Backend_Architecture.pdf');
  };

  return (
    <div>
      {loading && <LoadingOverlay />}
      <div className="header">
        <div>
          <h2 style={{ fontSize: '24px', fontWeight: '700' }}>Dashboard Overview</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: '14px' }}>Welcome back to your administration command center.</p>
        </div>
        <div style={{ display: 'flex', gap: '15px' }}>
             <button className="btn-primary" style={{ width: 'auto', padding: '10px 20px', margin: 0 }} onClick={fetchDashboardData}>
               Refresh Data
             </button>
        </div>
      </div>

      <div className="stat-cards">
        <div className="stat-card">
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                <h3>Faculty Members</h3>
                <span style={{ fontSize: '20px' }}></span>
            </div>
            <p style={{ fontSize: '32px', fontWeight: '800', color: 'var(--primary)' }}>
              {stats.faculty}
            </p>
          </div>
          <div style={{ marginTop: '15px', fontSize: '12px', color: '#10b981' }}>
             ↑ 12% from last month
          </div>
        </div>
        
        <div className="stat-card">
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                <h3>Active Students</h3>
                <span style={{ fontSize: '20px' }}></span>
            </div>
            <p style={{ fontSize: '32px', fontWeight: '800', color: '#10b981' }}>
              {stats.students}
            </p>
          </div>
          <div style={{ marginTop: '15px', fontSize: '12px', color: '#10b981' }}>
             ↑ 5% from last month
          </div>
        </div>

        <div className="stat-card">
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                <h3>Ongoing Courses</h3>
                <span style={{ fontSize: '20px' }}></span>
            </div>
            <p style={{ fontSize: '32px', fontWeight: '800', color: '#f59e0b' }}>
              {stats.courses}
            </p>
          </div>
          <div style={{ marginTop: '15px', fontSize: '12px', color: '#888' }}>
             Stabilized
          </div>
        </div>
      </div>

      <div className="table-container" style={{ border: '1px solid var(--border-color)', boxShadow: 'none' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
            <h3 style={{ fontSize: '18px', fontWeight: '600' }}>Recent Activity</h3>
            <button className="btn-small" style={{ color: 'var(--primary)', border: 'none', fontWeight: '600' }} onClick={() => router.push('/admin/logs')}>View All Logs</button>
        </div>
        <table>
          <thead>
            <tr>
              <th>User</th>
              <th>Action</th>
              <th>Details</th>
              <th>Time</th>
            </tr>
          </thead>
          <tbody>
            {logs.map(log => (
              <tr key={log.id}>
                <td style={{ fontWeight: '500' }}>{log.user_name || 'System'}</td>
                <td>
                    <span style={{ 
                        padding: '4px 10px', 
                        borderRadius: '20px', 
                        fontSize: '11px', 
                        fontWeight: '600',
                        backgroundColor: log.action.includes('CREATE') ? '#ecfdf5' : log.action.includes('LOGIN') ? '#eff6ff' : '#fef3c7',
                        color: log.action.includes('CREATE') ? '#10b981' : log.action.includes('LOGIN') ? '#3b82f6' : '#f59e0b'
                    }}>
                        {log.action}
                    </span>
                </td>
                <td style={{ color: '#4b5563' }}>{log.details}</td>
                <td style={{ color: '#94a3b8', fontSize: '12px' }}>{formatDate(log.created_at)}</td>
              </tr>
            ))}
            {logs.length === 0 && !loading && (
              <tr><td colSpan="4" style={{ textAlign: 'center', color: '#888', padding: '40px' }}>No activity logs found.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

